def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remaining_space = bins - item
    remainder = remaining_space % item
    return np.where(fit_mask, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remaining_space = bins - item
    extra_item_count = np.floor(remaining_space / item)
    return np.where(fit_mask, extra_item_count, -np.inf)
